package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.EmployeeAssetRequest; import EmployeeManagementSystem.repository.EmployeeAssetRequestRepository; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class EmployeeAssetRequestServiceImpl implements EmployeeAssetRequestService{
 private final EmployeeAssetRequestRepository repo; public EmployeeAssetRequestServiceImpl(EmployeeAssetRequestRepository r){repo=r;}
 public List<EmployeeAssetRequest> my(String u){return repo.findByUserIdOrderByCreatedAtDesc(u);} public List<EmployeeAssetRequest> all(){return repo.findAllByOrderByCreatedAtDesc();}
 public EmployeeAssetRequest create(EmployeeAssetRequest x,String u,String n){if(x.getAssetType()==null||x.getAssetType().isBlank())throw new IllegalArgumentException("Asset type is required."); if(!Set.of("LOW","MEDIUM","HIGH","URGENT").contains(Optional.ofNullable(x.getPriority()).orElse("MEDIUM").toUpperCase()))throw new IllegalArgumentException("Invalid priority."); if(x.getRequiredBy()!=null&&x.getRequiredBy().isBefore(LocalDate.now()))throw new IllegalArgumentException("Required date cannot be in the past."); if(repo.existsByUserIdAndAssetTypeAndStatusIn(u,x.getAssetType(),List.of("SUBMITTED","UNDER_REVIEW","APPROVED","ORDERED")))throw new IllegalArgumentException("An active request already exists for this asset type."); x.setId(null);x.setRequestNumber("AST-"+System.currentTimeMillis());x.setUserId(u);x.setEmployeeName(n);x.setStatus("SUBMITTED");return repo.save(x);}
 public EmployeeAssetRequest review(Long id,String s,String c,String r,String a,String ref){EmployeeAssetRequest x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Asset request not found."));if(!Set.of("UNDER_REVIEW","APPROVED","ORDERED","ISSUED","REJECTED","CANCELLED").contains(s))throw new IllegalArgumentException("Invalid request status."); if("ISSUED".equals(s)&& (ref==null||ref.isBlank()))throw new IllegalArgumentException("Asset reference is required when issuing an asset.");x.setStatus(s);x.setReviewerUserId(r);x.setReviewerComment(c);x.setAssignedTo(a);if(ref!=null&&!ref.isBlank())x.setAssetReference(ref);x.setReviewedAt(LocalDateTime.now());if("ISSUED".equals(s))x.setIssuedAt(LocalDateTime.now());return repo.save(x);}
}
